input.content:
export const dynamic = 'force-dynamic';

export default function ServerTimestamp() {
  const timestamp = new Date().toISOString();
  const formattedTime = new Date().toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    fractionalSecondDigits: 3,
    timeZoneName: 'short'
  });

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', marginTop: '20px' }}>
      <h2>Current Server Timestamp</h2>
      <p><strong>ISO Format:</strong> {timestamp}</p>
      <p><strong>Formatted Time:</strong> {formattedTime}</p>
      <p><strong>Timestamp (ms since epoch):</strong> {Date.now()}</p>
      <p style={{ marginTop: '10px', fontSize: '0.9em', color: '#666' }}>
        This timestamp is generated on the server for each request and will be different on every page load.
      </p>
    </div>
  );
}

